#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using Cysharp.Threading.Tasks;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public class LanguagePackReaderZipV0 : LanguagePackReaderV0, IResourcePackReaderZip
    {
        public LanguagePackReaderZipV0(MainManager main) : base(main)
        {
        }
        public override async UniTask<ResourcePack?> ReadPack(string key, string path)
        {
            using var stream = File.Open(path, FileMode.Open);
            return await ReadPack(key, stream);
        }
        public async UniTask<ResourcePack?> ReadPack(string key, byte[] bytes)
        {
            using var memory = new MemoryStream(bytes);
            return await ReadPack(key, memory);
        }
        public async UniTask<ResourcePack?> ReadPack(string key, Stream stream)
        {
            try
            {
                using var archive = new ZipArchive(stream);
                var packReadData = await UniTask.RunOnThreadPool(() => ReadPackData(key, archive));
                if (packReadData == null)
                    return null;
                var pack = new ResourcePack(key);

                await UniTask.SwitchToMainThread();

                ApplyReadData(pack, packReadData, (p, n) => ReadTexture2DZip(archive, p, n));

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包{key}失败：{e}");
                return null;
            }
        }
        private async UniTask<PackReadData> ReadPackData(string key, ZipArchive archive)
        {
            var packData = new PackReadData(key);
            var entries = archive.Entries.ToArray();
            foreach (var entry in entries)
            {
                if (string.IsNullOrEmpty(entry.Name))
                    continue;

                if (string.IsNullOrEmpty(Path.GetExtension(entry.FullName)))
                    continue;

                var fullPath = entry.FullName.Replace("\\", "/");
                var splitedPaths = fullPath.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                if (splitedPaths.Length < 3 || splitedPaths[0] != "assets")
                    continue;
                var nsp = splitedPaths[1];
                var lang = splitedPaths[2].Replace('_', '-');
                var filename = splitedPaths[3];
                if (splitedPaths.Length == 4)
                {
                    var dir = Path.Combine(splitedPaths[0], splitedPaths[1], splitedPaths[2]);
                    await ReadPackForEntry(archive, entry, nsp, lang, filename, dir, packData);
                }
            }
            return packData;
        }
        private async UniTask ReadPackForEntry(ZipArchive archive, ZipArchiveEntry entry, string nsp, string lang, string filename, string dir, PackReadData pack)
        {
            if (Path.GetExtension(filename) == ".mo")
            {
                // 加载MO翻译文件。
                await ReadPackCatalog(entry, lang, filename, pack);
            }
            else if (filename == SPRITE_MANIFEST_FILENAME)
            {
                await ReadPackSprites(archive, entry, nsp, lang, dir, pack);
            }
        }
        private async UniTask ReadPackCatalog(ZipArchiveEntry entry, string lang, string filename, PackReadData pack)
        {
            var filenameWithoutExt = Path.GetFileNameWithoutExtension(filename);
            var catalog = await entry.ReadCatalogAsync(lang);

            if (!pack.catalogs.TryGetValue(lang, out var catalogs))
            {
                catalogs = new Dictionary<string, Catalog>();
                pack.catalogs.Add(lang, catalogs);
            }
            catalogs.Add(filenameWithoutExt, catalog);
        }
        private async UniTask<Catalog> LoadPackMOFileDirectory(string moFile, string lang)
        {
            using (var stream = File.Open(moFile, FileMode.Open))
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    await stream.CopyToAsync(memory);
                    memory.Seek(0, SeekOrigin.Begin);
                    return new Catalog(memory, new CultureInfo(lang));
                }
            }
        }
        private async UniTask ReadPackSprites(ZipArchive archive, ZipArchiveEntry entry, string nsp, string lang, string dir, PackReadData pack)
        {
            // 加载Sprite Manifest文件。
            var manifestJson = await entry.ReadStringAsync(Encoding.UTF8);
            var manifest = JsonConvert.DeserializeObject<LocalizedSpriteManifest>(manifestJson);
            if (manifest != null)
            {
                ReadPackSpriteManifest(archive, nsp, lang, dir, pack, manifest);
            }
        }
        private void ReadPackSpriteManifest(ZipArchive archive, string nsp, string lang, string dir, PackReadData packData, LocalizedSpriteManifest manifest)
        {
            // 加载Sprite。
            if (manifest.sprites != null)
            {
                foreach (var localizedSprite in manifest.sprites)
                {
                    if (string.IsNullOrEmpty(localizedSprite.texture))
                        continue;
                    if (string.IsNullOrEmpty(localizedSprite.name))
                        continue;

                    var texturePath = Path.Combine(dir, "sprites", localizedSprite.texture).Replace("\\", "/");
                    var textureID = new NamespaceID(nsp, localizedSprite.texture);
                    var resID = new NamespaceID(nsp, localizedSprite.name);
                    var spriteRef = new SpriteReference(resID);
                    var spriteKey = new SpriteLookupKey(spriteRef, SpriteHelper.GetLanguageSpriteTag(lang));

                    var sliceData = new SliceData(spriteKey)
                    {
                        border = Vector4.zero,
                        extrude = 0,
                        meshType = SpriteMeshType.Tight,
                        pivot = new Vector2(localizedSprite.pivotX, localizedSprite.pivotY),
                        pixelsPerUnit = 100,
                        single = true,
                        spriteKey = spriteKey
                    };
                    var spriteEntry = new SpriteEntry(textureID, texturePath, sliceData);
                    packData.spriteEntries.Add(spriteEntry);
                }
            }
            // 加载Spritesheet。
            if (manifest.spritesheets != null)
            {
                foreach (var localizedSpritesheet in manifest.spritesheets)
                {
                    if (string.IsNullOrEmpty(localizedSpritesheet.texture))
                        continue;
                    if (string.IsNullOrEmpty(localizedSpritesheet.name))
                        continue;

                    var texturePath = Path.Combine(dir, "spritesheets", localizedSpritesheet.texture).Replace("\\", "/");
                    var textureID = new NamespaceID(nsp, localizedSpritesheet.texture);
                    var resID = new NamespaceID(nsp, localizedSpritesheet.name);
                    var spritesheetEntry = new SpritesheetEntry(textureID, texturePath);
                    if (localizedSpritesheet.slices != null)
                    {
                        for (int i = 0; i < localizedSpritesheet.slices.Length; i++)
                        {
                            var slice = localizedSpritesheet.slices[i];
                            var spriteRef = new SpriteReference(resID, i);
                            var spriteKey = new SpriteLookupKey(spriteRef, SpriteHelper.GetLanguageSpriteTag(lang));
                            var sliceData = new SliceData(spriteKey)
                            {
                                border = Vector4.zero,
                                extrude = 0,
                                meshType = SpriteMeshType.Tight,
                                pivot = new Vector2(slice.pivotX, slice.pivotY),
                                pixelsPerUnit = 100,
                                rect = new Rect(slice.x, slice.y, slice.width, slice.height),
                                spriteKey = spriteKey
                            };
                            spritesheetEntry.slices.Add(sliceData);
                        }
                    }
                    packData.spritesheetEntries.Add(spritesheetEntry);
                }
            }
        }
        private Texture2D? ReadTexture2DZip(ZipArchive archive, string path, string name = "texture2D")
        {
            var textureEntry = archive.Entries.FirstOrDefault(e => e.FullName.Replace("\\", "/") == path);

            if (textureEntry == null)
                return null;

            var bytes = textureEntry.ReadBytes();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
